macros/generate_schema_name.sql:
{#- Sovereign OS: a model's +schema is the EXACT Iceberg schema it lands in (personal_<uid> or the
    domain schema) — never dbt's default `<target.schema>_<custom>` concatenation. -#}
{% macro generate_schema_name(custom_schema_name, node) -%}
    {%- if custom_schema_name is none -%}
        {{ target.schema }}
    {%- else -%}
        {{ custom_schema_name | trim }}
    {%- endif -%}
{%- endmacro %}

models/gold/gold_accounts.sql:
-- gold_accounts — bronze layer of OS dataset ds_accts001 ("Accounts", domain sales).
-- Generated by Sovereign OS from the dataset definition; edit the dataset in the OS, not this file.
-- Scheduled sync of public.accounts (merge, cron "0 6 * * *" UTC) — see os/schedules.yml.
-- Late-data lookback: 0 minute(s) re-delivered each run; merge absorbs the overlap by key.

{{ config(materialized='incremental', incremental_strategy='merge', unique_key=['account_id'], on_schema_change='append_new_columns') }}

select * from {{ source('wh__public', 'accounts') }}
{% if is_incremental() %}
where "version" > (select max("version") from {{ this }})
{% endif %}

models/silver/silver_events.sql:
-- silver_events — bronze layer of OS dataset ds_events01 ("Events", domain sales).
-- Generated by Sovereign OS from the dataset definition; edit the dataset in the OS, not this file.
-- Scheduled sync of public.events (append, cron "*/15 * * * *" UTC) — see os/schedules.yml.
-- Late-data lookback: 15 minute(s) re-delivered each run; delete+insert on _batch_id makes a retry idempotent.

{{ config(materialized='incremental', incremental_strategy='delete+insert', unique_key='_batch_id', on_schema_change='append_new_columns') }}

select
  *,
  current_timestamp as _loaded_at,
  '{{ var("os_batch_id", invocation_id) }}' as _batch_id
from {{ source('wh__public', 'events') }}
{% if is_incremental() %}
where "updated_at" > (select max("updated_at") from {{ this }}) - interval '15' minute
{% endif %}

tests/generic/not_blank.sql:
{#- Sovereign OS quality rule `not_blank`: NULL or an empty / whitespace-only string is a
    violation. Same predicate as tabs/data/lib/dq.ts. -#}
{% test not_blank(model, column_name) %}
select *
from {{ model }}
where {{ column_name }} is null or trim(cast({{ column_name }} as varchar)) = ''
{% endtest %}

tests/generic/range.sql:
{#- Sovereign OS quality rule `range`: a NON-NULL value outside [min, max] is a violation
    (one-sided when only min or max is set). Same predicate as tabs/data/lib/dq.ts. -#}
{% test range(model, column_name, min=none, max=none) %}
{%- if min is none and max is none -%}
  {{ exceptions.raise_compiler_error("range needs a min and/or a max") }}
{%- endif -%}
select *
from {{ model }}
where {{ column_name }} is not null
  and (
    {%- if min is not none %} {{ column_name }} < {{ min }}{% endif -%}
    {%- if min is not none and max is not none %} or{% endif -%}
    {%- if max is not none %} {{ column_name }} > {{ max }}{% endif %}
  )
{% endtest %}
